// Route contract for this endpoint (read by wf.gateway.auth).
const route = {"method": "POST", "template": "/v1/profiles/extract", "require_user": true, "idempotent": false, "required_consents": ["terms", "privacy"], "roles": []};
const item = $input.first();
return [{ json: { ...item.json, t0: Date.now(), route }, binary: item.binary }];

// wf.api.profiles_extract > "Validate body"
// POST /v1/profiles/extract  {text (required, up to 2000 characters), jurisdiction (default: the
// account's), save (default false: return the profile without storing it)}
const gw = $input.first().json;
const b = gw.ctx.body || {};
const user = gw.ctx.user || {};
const details = [];
for (const k of Object.keys(b)) if (!['text', 'jurisdiction', 'save'].includes(k)) details.push({ field: k, issue: 'unknown_field' });
const text = typeof b.text === 'string' ? b.text.trim() : '';
if (!text) details.push({ field: 'text', issue: 'required' });
else if (Array.from(text).length > 2000) details.push({ field: 'text', issue: 'too_long', max: 2000 });
const jurisdiction = b.jurisdiction === undefined ? user.jurisdiction_code : b.jurisdiction;
if (typeof jurisdiction !== 'string' || !/^[A-Z]{2}(-[A-Z0-9]{1,3})?$/.test(jurisdiction)) details.push({ field: 'jurisdiction', issue: jurisdiction ? 'invalid_format' : 'required' });
if (b.save !== undefined && typeof b.save !== 'boolean') details.push({ field: 'save', issue: 'must_be_boolean' });
if (details.length) {
  return [{ json: { ok: false, status: 422, gw, error: { code: 'VALIDATION_FAILED', message: 'Request body is invalid', details } } }];
}
// Dates are resolved against today's date in UTC (D-061).
return [{ json: { ok: true, gw, save: b.save === true, text, jurisdiction, today: new Date().toISOString().slice(0, 10) } }];

// wf.api.profiles_extract > "Extract input"
const v = $input.first().json;
return [{ json: { text: v.text, jurisdiction: v.jurisdiction, today: v.today } }];

// wf.api.profiles_extract > "Save input": the extracted profile in the shape app.save_profile takes.
const v = $('Validate body').first().json;
const x = $input.first().json;
const p = x.profile;
const a = x.anchor && x.anchor.status === 'found' ? x.anchor.place : null;
const body = { ...p, jurisdiction_code: x.search_jurisdiction, anchor_lat: a ? a.lat : null, anchor_lng: a ? a.lng : null,
  extraction: { prompt_version_id: x.steps[0].prompt_version_id, model: x.steps[0].model, warnings: x.warnings } };
return [{ json: { params: [v.gw.ctx.user_id, JSON.stringify(body)] } }];

// wf.api.profiles_extract > "Build result" (and after "Save profile")
const v = $('Validate body').first().json;
const x = $('Extract').first().json;
if (!x.ok) {
  const status = x.error_code === 'UPSTREAM_UNAVAILABLE' ? 503 : 422;
  return [{ json: { ok: false, gw: v.gw, status, steps: x.steps,
    error: { code: x.error_code, message: x.error_code === 'UPSTREAM_UNAVAILABLE' ? 'The language model is unavailable'
      : 'The request could not be turned into a profile', details: [] }, log: { reason: 'profile_extraction', detail: x.error_code } } }];
}
let saved = null;
if (v.save) {
  const s = $input.first().json;
  if (s.error) {
    return [{ json: { ok: false, gw: v.gw, status: 422, steps: x.steps, error: { code: 'VALIDATION_FAILED', message: 'Profile could not be saved',
      details: [{ field: 'profile', issue: 'rejected_by_database' }] }, log: { reason: 'save_profile', detail: String(s.error.message || s.error).slice(0, 200) } } }];
  }
  saved = s.saved || null;
}
return [{ json: { ok: true, gw: v.gw, status: 200, steps: x.steps,
  data: { profile: x.profile, search_jurisdiction: x.search_jurisdiction, anchor: x.anchor, warnings: x.warnings, saved } } }];

// Shared by every API workflow > "Envelope"
// Input: either a handler result {ok:true, status, data, gw} or a rejection
// from the gateway or a handler {ok:false, status, error | replay+response}.
// Output: {status, response, finish} where finish is the app.api_finish payload.
const x = $input.first().json;
const gw = x.gw || x;                       // handlers carry the gateway item in x.gw
const t0 = gw.t0 || Date.now();
const latency = Date.now() - t0;
const requestId = gw.request_id || (gw.ctx && gw.ctx.request_id) || null;
let status, response;
if (x.replay) {
  status = x.status;
  response = x.response;                    // stored response, returned unchanged
} else if (x.ok) {
  status = x.status || 200;
  response = { request_id: requestId, data: x.data ?? {}, meta: { latency_ms: latency, ...(x.meta || {}) } };
} else {
  status = x.status || 500;
  const e = x.error || { code: 'INTERNAL', message: 'Internal error', details: [] };
  response = { request_id: requestId, error: { code: e.code, message: e.message, details: e.details || [] } };
}
const finish = {
  request_id: requestId,
  workflow: $workflow.name,
  n8n_execution_id: String($execution.id),
  user_id: (gw.ctx && gw.ctx.user_id) || '',
  channel: 'api',
  status_code: status,
  latency_ms: latency,
  error_code: response && response.error ? response.error.code : null,
  idempotency: gw.idempotency || null,
  idempotency_replay: !!x.replay,
  response_body: response,
  result_user_id: x.result_user_id || null,
  // agent steps of the request (spec 8.3), written to ai.agent_steps with the execution
  steps: Array.isArray(x.steps) ? x.steps : [],
  // reason and detail go to ai.executions.error only, never to the client
  error_detail: x.log ? [x.log.reason, x.log.detail].filter(Boolean).join(': ').slice(0, 500) : null,
};
const headers = { 'X-Request-Id': requestId || '', 'Cache-Control': 'no-store' };
if (status === 429) {
  const d = (response.error && response.error.details || []).find((y) => y.retry_after_s);
  if (d) headers['Retry-After'] = String(d.retry_after_s);
}
return [{ json: { status, response, finish, headers } }];
